def run_wordfilter_ops(words, queries):
    root = {}

    for idx, word in enumerate(words):
        n = len(word)
        for j in range(n + 1):
            combined = word[j:] + '#' + word
            node = root
            node[-1] = idx
            for ch in combined:
                node = node.setdefault(ch, {})
                node[-1] = idx

    def search(prefix, suffix):
        combined = suffix + '#' + prefix
        node = root
        for ch in combined:
            if ch not in node:
                return -1
            node = node[ch]
        return node.get(-1, -1)

    return [search(p, s) for p, s in queries]

